{
  "correction_rules": [
    "Adjust forecasts downward if recent history shows persistent downward drift and sentiment is neutral or negative.",
    "Avoid over-optimistic spikes in forecasts following recent price rallies; cap upward momentum at 5-10% above recent peak.",
    "When sentiment is consistently 0.00, assume no strong directional bias; use mean reversion or simple moving average smoothing.",
    "If true outcome consistently exceeds forecast by >3% over 3-5 days, reduce forecast slope to align with mean reversion trend.",
    "For horizon >14 days, apply exponential decay to recent forecast weights to reduce lagged bias.",
    "If sentiment history shows any positive signal (e.g., >0.00), slightly increase forecast volatility to reflect potential sentiment-driven volatility."
  ]
}
